const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometries
  const blueLagoon = ee.Geometry.Point([-22.4495, 63.8804]); // Blue Lagoon, Iceland
  const reykjavik = ee.Geometry.Point([-21.9426, 64.1466]); // Reykjavík, Iceland

  // Buffer for area comparison (500m radius)
  const blueLagoonBuffer = blueLagoon.buffer(500);
  const reykjavikBuffer = reykjavik.buffer(500);

  // 2. Define date for November 24, 2024
  const targetDate = '2024-11-24';
  const startDate = ee.Date('2024-11-01');
  const endDate = ee.Date('2024-12-01');

  // 3. Try VIIRS DNB Monthly collection first
  let viirsCol = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V21')
    .filterDate(startDate, endDate)
    .select('avg_rad');

  // Check collection size
  const colSize = viirsCol.size().getInfo();
  console.log(`Monthly VIIRS images for Nov 2024: ${colSize}`);

  if (colSize === 0) {
    // Try daily VIIRS
    console.log('Trying daily VIIRS data...');
    viirsCol = ee.ImageCollection('NOAA/VIIRS/DNB/DAILY_V21')
      .filterDate(ee.Date(targetDate).advance(-2, 'day'), 
                  ee.Date(targetDate).advance(2, 'day'))
      .select('avg_rad');

    const dailySize = viirsCol.size().getInfo();
    console.log(`Daily VIIRS images around ${targetDate}: ${dailySize}`);

    if (dailySize === 0) {
      // Try historical data from same date in previous year
      console.log('Trying historical data (2023)...');
      viirsCol = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V21')
        .filterDate('2023-11-01', '2023-12-01')
        .select('avg_rad');

      const histSize = viirsCol.size().getInfo();
      console.log(`Historical VIIRS images for Nov 2023: ${histSize}`);

      if (histSize === 0) {
        console.log('No VIIRS data found.');
        console.log('<answer>C1</answer>');
        return;
      }
    }
  }

  // 4. Get the image (first one in collection for monthly, median for daily)
  let img;
  if (viirsCol.size().getInfo() > 1) {
    img = viirsCol.median(); // For daily composite
  } else {
    img = viirsCol.first(); // For monthly data
  }

  // 5. Extract brightness values
  const blueLagoonStats = img.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: blueLagoonBuffer,
    scale: 1000,
    maxPixels: 1e9,
  }).getInfo();

  const reykjavikStats = img.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: reykjavikBuffer,
    scale: 1000,
    maxPixels: 1e9,
  }).getInfo();

  const blueLagoonBrightness = blueLagoonStats.avg_rad;
  const reykjavikBrightness = reykjavikStats.avg_rad;

  console.log(`Blue Lagoon brightness: ${blueLagoonBrightness}`);
  console.log(`Reykjavík brightness: ${reykjavikBrightness}`);

  // 6. Check for valid values
  if (blueLagoonBrightness === null || reykjavikBrightness === null || 
      isNaN(blueLagoonBrightness) || isNaN(reykjavikBrightness)) {
    console.log('One or both values are invalid.');
    console.log('<answer>C3</answer>');
    return;
  }

  // 7. Compare and output answer
  if (blueLagoonBrightness > reykjavikBrightness) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
